#!/usr/bin/env bash
# Runs ReDeEP across the LLaMA family on the paper's setting: RAGTruth
# test split, responses generated by llama-2-7b-chat. Ungated HF mirrors
# are used so no Meta licence / HF token is required.
cd "$(dirname "$0")/.."
PY="${PY:-/c/Users/Adithya K/venvs/deepLenv/Scripts/python.exe}"
COMMON="--split test --response_models llama-2-7b-chat --n_per_class 0 --max_len 1024 --max_prompt_chars 6000"
export PYTHONIOENCODING=utf-8
run() {  # tag model [extra args]
  tag=$1; model=$2; shift 2
  echo "===== $tag ($model) $(date)"
  "$PY" scripts/run_pipeline.py --model "$model" --tag "$tag" $COMMON "$@" > "data/logs/$tag.log" 2>&1
  echo "  exit=$? $(date)"; tail -n 25 "data/logs/$tag.log" | grep -A30 "Single held-out"
}
run tinyllama_1.1b   TinyLlama/TinyLlama-1.1B-Chat-v1.0
run llama3.2_1b      unsloth/Llama-3.2-1B-Instruct
run llama3.2_3b_4bit unsloth/Llama-3.2-3B-Instruct --load_in_4bit
run llama2_7b_4bit   NousResearch/Llama-2-7b-chat-hf --load_in_4bit
